import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it.todo("should return an empty grid for an empty grid");
  it.todo("should let a single live cell die from underpopulation");
  it.todo("should let two adjacent live cells die from underpopulation");
  it.todo("should let a live cell with two live neighbors survive");
  it.todo("should let a live cell with three live neighbors survive");
  it.todo("should let a live cell with more than three live neighbors die from overpopulation");
  it.todo("should bring a dead cell with exactly three live neighbors to life");
  it.todo("should keep a block unchanged as a still life");
  it.todo("should oscillate a vertical blinker into a horizontal blinker");
  it.todo("should oscillate a horizontal blinker back into a vertical blinker");
  it.todo("should handle cells at negative coordinates");
});
